SELECT 
FROM biz_company


        AND company_nm LIKE CONCAT('%', #{companyNm}, '%')


        AND biz_no LIKE CONCAT('%', #{bizNo}, '%')


        AND status_cd = #{statusCd}


        AND use_yn = #{useYn}


ORDER BY company_id DESC
LIMIT #{limit}

